5	/**
6	 * Single source of truth for what a "normalized" owner telephone is: the E.164 form. Both
7	 * {@link ValidateNewOwner} (which enforces the rule and stores the E.164 value) and
8	 * {@link CheckTelephoneUnique} (which compares against stored owners) normalize through here, so the
9	 * two cannot drift apart.
10	 *
11	 * <p>Normalization strips spaces, dashes and brackets, then forms the canonical E.164 string:
12	 * <ul>
13	 *   <li>a leading {@code '+'} and country code are kept as-is;</li>
14	 *   <li>otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
15	 *       the national digits.</li>
16	 * </ul>
17	 * The result must be a {@code '+'} followed by 8 to 15 digits; anything else (non-digit leftovers, or a
18	 * digit count outside that range) is not valid E.164 and yields {@code null}.
19	 */
20	final class OwnerTelephone {
21	
22	    /** A valid E.164 value: '+' then 8 to 15 digits. */
23	    private static final Pattern E164 = Pattern.compile("^\\+[0-9]{8,15}$");
24	
25	    /** Characters removed before interpreting the number: spaces, dashes and brackets. */
26	    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");
27	
28	    private OwnerTelephone() {
29	    }
30	
31	    /**
32	     * Returns the E.164 form of {@code telephone}, or {@code null} when it cannot form valid E.164.
33	     */
34	    static String toE164(String telephone) {
35	        if (telephone == null) {
36	            return null;
37	        }
38	        String cleaned = SEPARATORS.matcher(telephone).replaceAll("");
39	        String digits;
40	        if (cleaned.startsWith("+")) {
41	            // Keep the explicit country code; the '+' is re-added below.
42	            digits = cleaned.substring(1);
43	        }
44	        else {
45	            // No country code: assume +61 and drop a single leading '0' from the national digits.
46	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
47	            digits = "61" + national;
48	        }
49	        String e164 = "+" + digits;
50	        return E164.matcher(e164).matches() ? e164 : null;
51	    }
52	}
