===== MissingOwnerFieldsException.java =====
package org.springframework.samples.petclinic.rest.escalation;

import java.util.List;

/**
 * Thrown when a request to create an owner omits or blanks one or more required fields.
 * Carries the names of the offending fields so {@link MissingOwnerFieldsExceptionHandler}
 * can report them in the response's {@code errors} array. Checked so it appears in the
 * function's {@code throws} clause and is routed as an escalation.
 */
public class MissingOwnerFieldsException extends Exception {

    private final List<String> fields;

    public MissingOwnerFieldsException(List<String> fields) {
        super("Missing or blank required owner fields: " + fields);
        this.fields = List.copyOf(fields);
    }

    public List<String> getFields() {
        return this.fields;
    }
}

===== MissingOwnerFieldsExceptionHandler.java =====
package org.springframework.samples.petclinic.rest.escalation;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;

/**
 * Responds 400 with an RFC-7807 {@link ProblemDetail} (built through the shared {@link ProblemDetails}
 * helper, like every other handler in this package) whose {@code errors} array lists the name of each
 * required owner field that was missing or blank, e.g. {@code "errors":["city","telephone"]}.
 */
public class MissingOwnerFieldsExceptionHandler {

    public void handle(@Parameter MissingOwnerFieldsException ex,
            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
                "The request is missing one or more required owner fields");
        detail.setProperty("errors", ex.getFields());
        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
    }
}

===== InvalidTelephoneException.java =====
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a request to create an owner carries a telephone that cannot be normalized to valid
 * E.164 (a '+' followed by 8 to 15 digits). Carries the value as submitted so
 * {@link InvalidTelephoneExceptionHandler} can report what was actually seen. Checked so it appears in
 * the function's {@code throws} clause and is routed as an escalation.
 */
public class InvalidTelephoneException extends Exception {

    private final String telephone;

    public InvalidTelephoneException(String telephone) {
        super("Telephone could not be normalized to valid E.164 (+ then 8 to 15 digits): '"
                + telephone + "'");
        this.telephone = telephone;
    }

    public String getTelephone() {
        return this.telephone;
    }
}

